import {mkdtemp,mkdir,rm,writeFile} from 'node:fs/promises';import path from 'node:path';import os from 'node:os';import {JobRunner} from '../../../dist/jobs/runner.js';
const root=await mkdtemp(path.join(os.tmpdir(),'forge-log-failure-')),runner=new JobRunner(root);await runner.ready;try{const job=await runner.start({projectId:'p',key:'one',requestHash:'one',steps:[{name:'log',executable:process.execPath,args:[path.resolve('tests/fixtures/jobs/worker.mjs')],task:'log',params:{waitFor:path.join(root,'ready')},cwd:process.cwd(),timeoutMs:2000}]});await mkdir(path.join(root,job.id,'log.txt'));await writeFile(path.join(root,'ready'),'1');let state;for(let n=0;n<300;n++){state=await runner.status('p',job.id);if(!['queued','running'].includes(state.status))break;await new Promise(r=>setTimeout(r,10));}console.log(JSON.stringify({status:state.status}));}finally{await runner.close();await rm(root,{recursive:true,force:true});}
